  if($method==='GET'&&str_starts_with($path,'/codes/?')){parse_str(parse_url($path,PHP_URL_QUERY),$q);$items=array_values(array_filter($codes,fn($r)=>$r['name']===$q['name']));return ['items'=>$items,'pages'=>1];}
  if($method==='GET'&&str_starts_with($path,'/codes/')){$code=substr($path,7);$r=$codes[$code]??null;return $r?['exists'=>true,'is_valid'=>$r['status']==='active']+$r:['exists'=>false,'is_valid'=>false];}
  if($method==='POST'&&$path==='/codes/activate'){$r=$codes[$body['code']];$codes[$body['code']]['status']='activated';return ['success'=>true,'operation_id'=>gc_uuid(),'currency_code'=>'RUB','activated_amount'=>$r['amount'],'commission_charged'=>'5.00','activated_at'=>gmdate('c')];}
  if($method==='DELETE'&&str_starts_with($path,'/codes/')){$codes[substr($path,7)]['status']='deactivated';return ['success'=>true];}
  throw new RuntimeException('Unexpected mock provider call');
 });
